public static String testableHtml(
      PageData pageData,
      boolean includeSuiteSetup
      ) throws Exception {
          WikiPage wikiPage = pageData.getWikiPage();
          StringBuffer buffer = new StringBuffer();
          if (pageData.hasAttribute("Test")) {
              appendSetupPages(buffer, wikiPage, includeSuiteSetup);
          }
          buffer.append(pageData.getContent());
          if (pageData.hasAttribute("Test")) {
              appendTeardownPages(buffer, wikiPage, includeSuiteSetup);
          }
          pageData.setContent(buffer.toString());
          return pageData.getHTML();
      }

      private static void appendSetupPages(StringBuffer buffer, WikiPage wikiPage, boolean includeSuiteSetup) throws Exception {
          if (includeSuiteSetup) {
              appendInheritedPage(SuiteResponder.SUITE_SETUP_NAME, "setup", buffer, wikiPage);
          }
          appendInheritedPage("SetUp", "setup", buffer, wikiPage);
      }

      private static void appendTeardownPages(StringBuffer buffer, WikiPage wikiPage, boolean includeSuiteSetup) throws Exception {
          appendInheritedPage("TearDown", "teardown", buffer, wikiPage);
          if (includeSuiteSetup) {
              appendInheritedPage(SuiteResponder.SUITE_TEARDOWN_NAME, "teardown", buffer, wikiPage);
          }
      }

      private static void appendInheritedPage(String pageName, String type, StringBuffer buffer, WikiPage wikiPage) throws Exception {
          WikiPage page = PageCrawlerImpl.getInheritedPage(pageName, wikiPage);
          if (page != null) {
              WikiPagePath pagePath = page.getPageCrawler().getFullPath(page);
              String pagePathName = PathParser.render(pagePath);
              buffer.append("! include -" + type + " .")
                    .append(pagePathName)
                    .append("\n");
          }
      }
